# ------------------------------------------------------------------ OA 16 · clase 2
L(OA, 2,
  "Aprenderé a observar modelos de estilo directo e indirecto y a identificar sus marcas formales: signos, verbos de habla, nexos y cambios de persona.",
  ["Distingo estilo directo e indirecto.", "Conozco los verbos de habla."],
  ["Para escribir con estilo directo e indirecto, primero se investigan sus marcas en modelos. En el directo: raya o comillas; los dos puntos antes de la cita («Dijo: “Voy”»); la mayúscula inicial de lo dicho; los signos de interrogación y exclamación de la pregunta original. El verbo de habla puede ir antes o después.",
   "En el indirecto: nexo «que» para enunciados (Dijo que iba) o «si» y palabras interrogativas para preguntas (Preguntó si iba; Preguntó dónde iba); desaparecen raya y comillas; no se escriben signos de interrogación en las preguntas indirectas; cambia la persona (de «yo» a «él») y a veces el tiempo: con un verbo de habla en pasado, «tengo» suele pasar a «tenía» (la clase siguiente detalla estos cambios). Los verbos de habla varían según la intención: afirmó, aseguró, preguntó, pidió, ordenó, sugirió.",
   "Elegir bien el verbo de habla aporta significado. «Dijo» es neutro; «gritó» indica volumen; «susurró», bajo volumen; «sugirió», una propuesta suave; «ordenó», una instrucción fuerte. Al escribir, evita repetir «dijo» siempre y conserva el sentido de lo dicho."],
  [("nexo", "palabra que une dos partes, como «que» o «si»"), ("pregunta indirecta", "pregunta contada sin signos de interrogación, con «si» o una palabra interrogativa"), ("verbo de habla", "verbo que introduce lo dicho"), ("mayúscula inicial", "letra mayúscula con que comienza lo dicho en el estilo directo")],
  [("Hallar las marcas",
    "Modelo de ejemplo: Dijo: «Voy a estudiar». / Dijo que iba a estudiar. ¿Qué cambia entre ambos?",
    ["Desaparecen los dos puntos y las comillas.", "Aparece «que».", "Cambia «voy» por «iba»."],
    "Desaparecen los dos puntos y comillas, aparece «que» y cambia el tiempo"),
   ("Pregunta directa e indirecta",
    "Directa: Luis preguntó: «¿Dónde vives?». Escríbela en indirecto.",
    ["Quito signos y comillas.", "Uso «dónde».", "Cambio «vives» a «vivía»."],
    "Luis preguntó dónde vivía")],
  [("Escribir signos de interrogación en la pregunta indirecta.", "No lleva signos.", "Escribe «preguntó si…» o «preguntó dónde…»."),
   ("Repetir «dijo» en todas las frases.", "Pierde matices.", "Elige un verbo según la intención.")],
  ([E("¿Qué nexo introduce un enunciado en indirecto: «que» o «si»?", "«Que»", "Introduce lo dicho."),
    E("¿La pregunta indirecta lleva signos de interrogación: sí o no?", "No", "Se cuenta sin ellos."),
    E("¿«Susurró» indica volumen bajo o alto?", "Bajo", "Es hablar muy bajito.")],
   [E("Elige la pregunta indirecta correcta. A) «Preguntó si venía» B) «Preguntó: ¿si venía?»", "A) «Preguntó si venía»", "No lleva signos."),
    E("¿Qué marca tiene el directo y no el indirecto? A) comillas o raya B) el nexo «que»", "A) comillas o raya", "Señalan palabras exactas."),
    E("¿Cuál verbo expresa una orden fuerte? A) ordenó B) sugirió", "A) ordenó", "Indica instrucción firme.")],
   [E("Clasifica con D o I: 1) Ana preguntó: «¿Dónde está la sala?». 2) Ana preguntó dónde estaba la sala. 3) Ana dijo que ya llegaba. Escribe las letras en orden.", "D, I, I", "La primera usa signos y comillas; las otras no."),
    E("Escribe en indirecto: Marta dijo: «Tengo frío». A) Marta dijo que tenía frío B) Marta dijo que tengo frío", "A) Marta dijo que tenía frío", "Cambia el presente a imperfecto."),
    E("Escribe en indirecto: Pablo preguntó: «¿Terminaste el informe?». A) Pablo preguntó si había terminado el informe B) Pablo preguntó: si terminaste el informe", "A) Pablo preguntó si había terminado el informe", "Usa «si», sin signos ni dos puntos; el verbo pasa a un tiempo del pasado, como se detalla en la clase siguiente.")],
   [E("Un compañero escribe «Dijo que “voy a ir”». ¿Qué mezcla? A) indirecto con comillas del directo B) directo puro", "A) indirecto con comillas del directo", "No debe mezclarse."),
    E("¿Por qué conviene variar los verbos de habla? A) para dar matices y evitar repeticiones B) porque los verbos de habla no cambian el significado", "A) para dar matices y evitar repeticiones", "Cada verbo expresa una intención distinta: «susurró» no es lo mismo que «ordenó».")],
   [E("Un personaje dice en voz muy baja «Ya llegó la profesora». ¿Qué verbo de habla expresa mejor esa manera de decir? A) susurró B) gritó", "A) susurró", "«Susurró» indica volumen bajo; «gritó» indica volumen alto."),
    E("Un compañero afirma que la pregunta indirecta «Preguntó dónde vivía» debe llevar signos de interrogación porque es una pregunta. ¿Qué le respondes? A) que no los lleva, porque no reproduce las palabras exactas B) que los lleva siempre que haya un verbo de habla", "A) que no los lleva, porque no reproduce las palabras exactas", "Los signos pertenecen a la pregunta original del estilo directo; la indirecta se cuenta con «si» o una palabra interrogativa.")]),
  [E("Modelo: «Pidió que cerraran la puerta». ¿Qué verbo de habla introduce el indirecto? A) pidió B) cerraran", "A) pidió", "Es el verbo que introduce lo dicho.")],
  [E("¿Qué nexo usa la pregunta indirecta con respuesta sí o no?", "«Si»", "Introduce preguntas sin palabra interrogativa."),
   E("¿Qué cambia a veces en el indirecto?", "La persona y el tiempo", "Se adaptan a quien narra."),
   E("¿Qué marca el directo?", "Comillas o raya", "Señalan las palabras exactas.")],
  ("Observa estos modelos y completa una ficha con tres columnas (marcas del directo, marcas del indirecto, verbos de habla): (1) Dijo: «Llegaré tarde». (2) Dijo que llegaría tarde. (3) Preguntó: «¿Quién viene?». (4) Preguntó quién venía.",
   "Directo: dos puntos, comillas, mayúscula, signos. Indirecto: «que», quién, tiempo cambiado. Verbos: dijo, preguntó.",
   ["identifica marcas formales", "reconoce cambios de tiempo", "lista verbos de habla"], ["ficha de tres columnas"], ["no ver el cambio de tiempo"], "Subraya en cada modelo la marca que anotaste."),
  "Lee una noticia y subraya los verbos de habla.",
  "Escribe una lista de diez verbos de habla y su intención.")

# ------------------------------------------------------------------ OA 16 · clase 3
L(OA, 3,
  "Aprenderé a planificar la transformación del estilo directo al indirecto: qué cambios de persona, de tiempo verbal y de expresiones de tiempo y lugar corresponden.",
  ["Reconozco las marcas formales de cada estilo.", "Sé conjugar verbos en pasado y futuro."],
  ["Al pasar del directo al indirecto cambian tres cosas. La persona: «Yo traje mi cuaderno» → Dijo que él había traído su cuaderno. El tiempo verbal, cuando el verbo de habla está en pasado. Las expresiones de tiempo y lugar: hoy → ese día; ayer → el día anterior; mañana → al día siguiente; aquí → allí; este → ese.",
   "Cambios de tiempo con verbo de habla en pasado: presente → pretérito imperfecto («Tengo hambre» → dijo que tenía hambre); pretérito perfecto simple y compuesto → pluscuamperfecto («Llegué» o «He llegado» → dijo que había llegado); futuro → condicional («Iré» → dijo que iría); imperativo → subjuntivo («Cierra» → pidió que cerrara). Si el verbo de habla está en presente, el tiempo no cambia: «Dice: “Tengo hambre”» → dice que tiene hambre.",
   "Antes de escribir, conviene hacer una tabla: frase directa, quién habla, cuándo habla, verbo de habla. Luego se aplican los cambios paso a paso. Planificar evita errores como dejar «mañana» en el indirecto o mantener el presente cuando corresponde el imperfecto."],
  [("pluscuamperfecto", "tiempo verbal pasado anterior a otro pasado: había llegado"), ("condicional", "tiempo verbal de posibilidad o futuro desde el pasado: iría"), ("imperfecto", "tiempo pasado que describe acciones en desarrollo: tenía"), ("expresión deíctica", "palabra que depende del momento o lugar, como hoy o aquí")],
  [("Aplicar los cambios",
    "Directo: Rosa dijo: «Mañana iré al museo». Pásalo a indirecto.",
    ["Verbo de habla en pasado.", "«Mañana» → «al día siguiente».", "«Iré» → «iría»."],
    "Rosa dijo que al día siguiente iría al museo"),
   ("Verbo de habla en presente",
    "Directo: Rosa dice: «Tengo hambre». Pásalo a indirecto.",
    ["El verbo de habla está en presente.", "El tiempo no cambia.", "Cambia solo la persona."],
    "Rosa dice que tiene hambre")],
  [("Mantener «mañana» en el indirecto.", "Depende del momento en que se habló.", "Usa «al día siguiente»."),
   ("Cambiar el tiempo cuando el verbo de habla está en presente.", "No hace falta.", "Revisa el tiempo del verbo de habla.")],
  ([E("«Hoy» se transforma en el indirecto en «ese día». ¿Verdadero o falso?", "Verdadero", "Es el cambio habitual con verbo de habla en pasado."),
    E("«Iré» pasa en el indirecto (verbo de habla en pasado) a... A) iría B) iré", "A) iría", "El futuro pasa a condicional."),
    E("«Tengo» pasa en el indirecto (verbo de habla en pasado) a... A) tenía B) tendré", "A) tenía", "El presente pasa a imperfecto.")],
   [E("Directo: —Ayer llegué tarde —dijo Teo. Indirecto: Teo dijo que ____ llegado tarde. A) había B) hubiera", "A) había", "El pretérito pasa a pluscuamperfecto."),
    E("Directo: —Cierra la ventana —pidió Ana. Indirecto: Ana pidió que ____ la ventana. A) cerrara B) cierra", "A) cerrara", "El imperativo pasa a subjuntivo."),
    E("Directo: —Estoy aquí —dijo Pía. Se cuenta la frase desde otro lugar. Indirecto: Pía dijo que estaba ____. A) allí B) aquí", "A) allí", "Cambia la referencia de lugar.")],
   [E("Une cada frase con su indirecto: 1) «Tengo sueño». 2) «He terminado». 3) «Iré mañana». a) había terminado, b) tenía sueño, c) iría al día siguiente. Escribe 1-?, 2-?, 3-?", "1-b, 2-a, 3-c", "Presente→imperfecto, perfecto→pluscuamperfecto, futuro→condicional."),
    E("Directo: —Compré pan ayer —dijo Rita. Indirecto correcto. A) Rita dijo que había comprado pan el día anterior B) Rita dijo que compró pan ayer", "A) Rita dijo que había comprado pan el día anterior", "Cambian el tiempo y la expresión temporal."),
    E("Directo: —Yo traje mi cuaderno —dijo Pedro. Indirecto correcto. A) Pedro dijo que él había traído su cuaderno B) Pedro dijo que yo había traído mi cuaderno", "A) Pedro dijo que él había traído su cuaderno", "Cambian la persona y el posesivo.")],
   [E("Un compañero escribe: «Dijo que mañana vendría». El hecho es que habló ayer. ¿Qué corrige? A) cambiar «mañana» por «al día siguiente» B) cambiar «vendría» por «vendrá»", "A) cambiar «mañana» por «al día siguiente»", "La expresión depende del momento en que se habló; el condicional ya es el tiempo correcto."),
    E("Directo: «Dice: “Soy de Chile”». Un estudiante escribe «Dice que era de Chile». ¿Es correcto? Responde sí o no y por qué.", "No; el verbo de habla está en presente y no cambia el tiempo", "Debe ser «es de Chile».")],
   [E("Directo: —Mañana nos veremos aquí —dijo Gael. Se cuenta desde otro día y otro lugar. ¿Cuál es el indirecto correcto? A) Gael dijo que al día siguiente se verían allí B) Gael dijo que mañana nos veremos aquí", "A) Gael dijo que al día siguiente se verían allí", "Cambian la persona, el tiempo y las expresiones de tiempo y lugar."),
    E("Directo: —Esta semana he estudiado mucho —dijo Noa. Indirecto con verbo de habla en pasado. A) Noa dijo que esa semana había estudiado mucho B) Noa dijo que esta semana ha estudiado mucho", "A) Noa dijo que esa semana había estudiado mucho", "Cambian el demostrativo y el tiempo: «he estudiado» pasa a «había estudiado».")]),
  [E("Directo: Camila dijo: «Esta tarde estudiaré». Indirecto con verbo en pasado. A) Camila dijo que esa tarde estudiaría B) Camila dijo que esta tarde estudiará", "A) Camila dijo que esa tarde estudiaría", "Cambian el demostrativo y el tiempo.")],
  [E("¿Cómo se transforma «mañana» en indirecto con verbo en pasado?", "Al día siguiente", "Depende del momento en que se habló."),
   E("¿Cómo se transforma «he llegado»?", "Había llegado", "Pasa a pluscuamperfecto."),
   E("¿Cambia el tiempo si el verbo de habla está en presente?", "No", "Solo cambia la persona.")],
  ("Transforma a estilo indirecto, con verbo de habla en pasado: (1) —Hoy tengo prueba —dijo Mía. (2) —Mañana iré al museo —dijo Leo. (3) —Ayer perdí mi llave —dijo Sara. Escribe las tres frases y subraya cada cambio.",
   "(1) Mía dijo que ese día tenía prueba. (2) Leo dijo que al día siguiente iría al museo. (3) Sara dijo que el día anterior había perdido su llave.",
   ["cambia persona, tiempo y expresión temporal", "mantiene el sentido"], ["tres frases transformadas"], ["olvidar cambiar el tiempo"], "Revisa cada frase con la tabla de cambios."),
  "Escribe una frase con «mañana» y pásala a indirecto.",
  "Haz una tabla con cinco tiempos del directo y su equivalente en indirecto.")

